SCRIPTS = ROOT / "scripts"
FOLDER = re.compile(r"[0-9]{8}T[0-9]{6}Z-[a-z0-9-]{1,32}\Z")


def pattern(size, seed=0):
    """Incompressible-looking deterministic bytes (DEFLATE cannot shrink them much)."""
    out, block = bytearray(), seed.to_bytes(8, "little")
    while len(out) < size:
        block = hashlib.sha256(block).digest()
        out += block * 32
    return bytes(out[:size])


def backup_folder(receipt):
    return Path(receipt["destination"]) / receipt["folder"]


class BackupFixture(NativeStorageFixture):
    """NativeStorageFixture plus a backup into the output root itself (the product's work/backups layout)."""

    def plan(self, selected=None, **options):
        inventory = self.inventory()
        selected = selected or [row["key"] for row in inventory["entries"] if row["kind"] == "file"]
        options.setdefault("destination", self.output)
        return self.service.plan_backup(inventory=inventory, selected=selected, content_read_authorized=True, **options)

    def create(self, plan):
        return self.service.create_backup(plan=plan, expected_plan_sha256=plan_sha256(plan))


class NativeStorageTests(BackupFixture, unittest.TestCase):
    def test_private_archive_probe_and_records_actual_permissions(self):
        plan, backup = self.backup(selected=["r001/readme.txt"])
        restored = self.probe(backup)
        folder = backup_folder(backup)
        for path in (folder / "backup.zip", folder / "manifest.json", folder / "README.txt",
                     self.output / backup["attempt"], self.output / restored["attempt"],
                     self.output / ("outcome-backup-" + plan_sha256(plan) + ".json"),
                     self.output / ("outcome-restore-" + restored["plan_sha256"] + ".json"),
                     Path(restored["destination"]) / "r001" / "readme.txt"):
            ensure_private_file(path)
        ensure_private_directory(folder)
        ensure_private_directory(Path(restored["destination"]))
        ensure_private_directory(Path(restored["destination"]) / "r001")

    def test_verified_backup_restore_and_immutable_archive(self):
        plan, receipt = self.backup()
        attempt = json.loads((self.output / receipt["attempt"]).read_bytes())
        self.assertNotIn("exact_plan", attempt)
        self.assertEqual(attempt["plan_sha256"], plan_sha256(plan))
        self.assertEqual(attempt["entry_count"], len(plan["files"]))
        self.assertEqual((attempt["folder"], sorted(attempt["partials"])), (receipt["folder"], ["archive", "manifest", "readme"]))
        self.assertEqual(json.loads((self.output / attempt["plan_file"]).read_bytes()), plan)
        verified = self.service.verify_backup(receipt=receipt)
        self.assertTrue(verified["verified"])
        self.assertTrue(self.service.verify_outcome(plan=plan, expected_plan_sha256=plan_sha256(plan), receipt=receipt)["verification_passed"])
        self.assertFalse(receipt["encryption"])
        self.assertEqual(len(verified["manifest"]["files"]), 4)
        restore = self.service.plan_restore(receipt=receipt, destination=self.output / "restored")
        outcome = self.service.restore_backup(plan=restore, expected_plan_sha256=plan_sha256(restore))
        self.assertTrue(outcome["verified"])
        self.assertTrue(self.service.verify_outcome(plan=restore, expected_plan_sha256=plan_sha256(restore), receipt=outcome)["verification_passed"])
        self.assertEqual((self.output / "restored" / "r001" / "readme.txt").read_bytes(), b"fictional document\n")
        self.assertEqual((self.output / "restored" / "r001" / "notes" / "draft.md").read_bytes(), b"fictional draft\n")
        with self.assertRaises((StorageRefusal, ScopedFSError)):
            self.service.create_backup(plan=plan, expected_plan_sha256=plan_sha256(plan))
        with self.assertRaises((StorageRefusal, ScopedFSError, FileExistsError)):
            self.service.plan_restore(receipt=receipt, destination=self.output / "restored")

    def test_skipped_unbacked_files_visible_and_required_recovery_holds(self):
        inventory = self.inventory()
        selected = ["r001/readme.txt"]
        plan, receipt = self.backup(inventory, selected)
        self.assertTrue(any(row["key"] == "r001/copy.txt" and "not backed up" in row["reason"] for row in plan["skipped"]))
        with self.assertRaisesRegex(StorageRefusal, "Required recovery"):
            self.service.plan_cleanup(inventory=inventory, selected=selected, quarantine_destination=self.output / "quarantine", content_read_authorized=True)
        with self.assertRaisesRegex(StorageRefusal, "restoration probe"):
            self.service.plan_cleanup(inventory=inventory, selected=selected, quarantine_destination=self.output / "quarantine", content_read_authorized=True, recovery_backup=receipt)
        probe = self.probe(receipt)
        with self.assertRaisesRegex(StorageRefusal, "does not cover"):
            self.service.plan_cleanup(inventory=inventory, selected=["r001/copy.txt"], quarantine_destination=self.output / "quarantine", content_read_authorized=True, recovery_backup=receipt, recovery_verification=probe)
        with self.assertRaisesRegex(StorageRefusal, "protected"):
            self.service.plan_cleanup(inventory=inventory, selected=selected, quarantine_destination=self.output / "quarantine", content_read_authorized=True, recovery_backup=receipt, protected=selected)


class StreamingBackupTests(BackupFixture, unittest.TestCase):
    def test_streams_in_bounded_chunks_no_whole_reads(self):
        write_private_new(self.source / "big.bin", pattern(3 * scoped_base.CHUNK_BYTES + 5))
        pieces = []
        real = storage_backup._Member.write

        def counted(member, data):
            pieces.append((member.info.filename, len(data)))
            return real(member, data)
        with mock.patch.object(storage_backup._Member, "write", counted):
            receipt = self.create(self.plan())
        big = [size for name, size in pieces if name == "r001/big.bin"]
        self.assertEqual(sum(big), 3 * scoped_base.CHUNK_BYTES + 5)
        self.assertGreaterEqual(len(big), 4)
        self.assertTrue(all(0 < size <= scoped_base.CHUNK_BYTES for name, size in pieces if size))
        self.assertEqual(receipt["outcome"], "succeeded")
        # And statically: no whole-content read anywhere in the backup writer.
        source = (SCRIPTS / "storage_backup.py").read_text(encoding="utf-8")
        self.assertIn("force_zip64=True", source)
        self.assertNotIn("BytesIO", source)
        self.assertNotIn("read_bytes(", source)
        calls = [node for node in ast.walk(ast.parse(source)) if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute)
                 and node.func.attr == "read" and not node.args and not node.keywords]
        self.assertEqual(calls, [])

    def test_peak_memory_independent_of_file_size(self):
        peaks = {}
        for name, size in (("peak-small.bin", 2 * scoped_base.CHUNK_BYTES + 3), ("peak-large.bin", 8 * scoped_base.CHUNK_BYTES + 3)):
            write_private_new(self.source / name, pattern(size, seed=size))
            plan = self.plan([f"r001/{name}"], label=name.split(".")[0])
            tracemalloc.start()
            try:
                self.create(plan)
                peaks[name] = tracemalloc.get_traced_memory()[1]
            finally:
                tracemalloc.stop()
        # Four times the bytes, the same memory: a few chunks in flight, never the file or the archive.
        self.assertLess(abs(peaks["peak-large.bin"] - peaks["peak-small.bin"]), scoped_base.CHUNK_BYTES // 2, peaks)
        self.assertLess(peaks["peak-large.bin"], 6 * scoped_base.CHUNK_BYTES, peaks)

    def test_zip64_forced_and_more_than_65535_entries(self):
        count = 65_536 + 3
        rows = [{"entry": f"r001/f{index:05d}.txt", "root_id": "r001", "key": f"r001/f{index:05d}.txt", "relative_path": f"f{index:05d}.txt",
                 "kind": "file", "device": 1, "inode": index + 1, "mode": 0o100600, "size": 1, "mtime_ns": 0, "ctime_ns": 0, "nlink": 1,
                 "sha256": hashlib.sha256(bytes([index % 251])).hexdigest(), "attributes": 0} for index in range(count)]

        class Source:
            """Serves each fictional one-byte file through the writer, as RootBase.stream_to does."""
            root = self.source

            def stream_to(self, relative, *, expected, writer):
                writer(bytes([int(relative[1:6]) % 251]))
                return expected
        plan = {"files": rows, "label": "many"}
        with scoped_fs.open_root(str(self.output)) as destination:
            destination.mkdir("20260101T000000Z-many")
            with mock.patch.object(storage_backup.win32_files, "dacl_protected", return_value=None):
                written, record = self.service._write_archive(destination, "20260101T000000Z-many", scoped_base.new_partial_name(),
                                                              plan, {"r001": Source()})
        archive = self.output / "20260101T000000Z-many" / "backup.zip"
        data = archive.read_bytes()
        self.assertEqual(len(written), count)
        self.assertEqual(record["sha256"], hashlib.sha256(data).hexdigest())
        self.assertIn(b"PK\x06\x06", data)  # the ZIP64 end of central directory record
        self.assertIn(b"PK\x06\x07", data)  # and its locator
        self.assertEqual(struct.unpack("<H", data[-22 + 10:-22 + 12])[0], 0xFFFF)  # the classic count says "see ZIP64"
        with zipfile.ZipFile(archive) as reader:
            infos = reader.infolist()
            self.assertEqual(len(infos), count)
            self.assertTrue(all(info.flag_bits & 0x800 for info in infos))
        with open(archive, "rb") as stream:
            for info in (infos[0], infos[-1]):
                stream.seek(info.header_offset + 28)
                extra_length = struct.unpack("<H", stream.read(2))[0]
                stream.seek(info.header_offset + 30 + len(info.filename))
                self.assertEqual(struct.unpack("<H", stream.read(extra_length)[:2])[0], 1)  # forced ZIP64 extra in every header
            self.assertEqual(storage_verify.verify_archive(stream, written), count)

    def test_per_backup_folder_has_zip_manifest_readme(self):
        receipt = self.create(self.plan(label="weekly"))
        folder = backup_folder(receipt)
        self.assertTrue(FOLDER.fullmatch(receipt["folder"]) and receipt["folder"].endswith("-weekly"))
        self.assertEqual(sorted(os.listdir(folder)), ["README.txt", "backup.zip", "manifest.json"])
        lines = (folder / "manifest.json").read_bytes().split(b"\n")
        self.assertEqual(lines[-1], b"")
        header = json.loads(lines[0])
        self.assertEqual((header["kind"], header["format"], header["entry_count"]), ("backup_manifest", "json-lines", 4))
        entries = [json.loads(line) for line in lines[1:5]]
        with zipfile.ZipFile(folder / "backup.zip") as archive:
            self.assertEqual([info.filename for info in archive.infolist()], [row["entry"] for row in entries])
            self.assertTrue(all(info.flag_bits & 0x800 and info.compress_type == zipfile.ZIP_DEFLATED for info in archive.infolist()))
            self.assertEqual(archive.read("r001/notes/draft.md"), b"fictional draft\n")
        self.assertEqual({row["entry"] for row in entries}, {"r001/copy.txt", "r001/large.bin", "r001/notes/draft.md", "r001/readme.txt"})
        for row in entries:
            self.assertEqual(row["entry"], row["root_id"] + "/" + row["relative_path"])
            self.assertEqual(set(row) - set(self.plan()["files"][0]), {"crc32", "read_only", "dacl_protected", "changed"})
            self.assertIs(row["changed"], False)
            self.assertIs(type(row["crc32"]), int)
        self.assertEqual((receipt["outcome"], receipt["changed_count"], receipt["entry_count"]), ("succeeded", 0, 4))
        self.assertIn(receipt["disk_relation"], {"same", "different", "unknown"})
        self.assertEqual(receipt["disk_relation"], "same")  # the fixture's source and backup share one volume
        self.assertEqual(receipt["sources_synced"], [])
        self.assertIs(type(receipt["durable"]), bool)

    def test_readme_explains_restore_and_copying_elsewhere(self):
        receipt = self.create(self.plan())
        text = (backup_folder(receipt) / "README.txt").read_text(encoding="utf-8")
        for phrase in ("backup.zip", "manifest.json", "NOT encrypted", "With PatchCairn", "By hand", "any ZIP tool",
                       "another drive", "cloud storage", "r001: "):
            with self.subTest(phrase=phrase):
                self.assertIn(phrase, text)
        self.assertIn(str(self.source), text)
        self.assertEqual(receipt["readme_sha256"], hashlib.sha256((backup_folder(receipt) / "README.txt").read_bytes()).hexdigest())

    def test_source_changed_during_backup_is_reported(self):
        plan = self.plan()
        real = storage_backup._Member.write

        def change_the_next_file(member, data):
            if member.info.filename == "r001/copy.txt" and not member.size:
                with open(self.source / "large.bin", "r+b") as stream:  # a file the backup has not reached yet
                    stream.write(b"CHANGED")
            return real(member, data)
        with mock.patch.object(storage_backup._Member, "write", change_the_next_file):
            receipt = self.create(plan)
        self.assertEqual((receipt["outcome"], receipt["changed_count"]), ("partial", 1))
        verified = self.service.verify_backup(receipt=receipt, archive_data=False)
        changed = verified["manifest"]["changed"]
        self.assertEqual([row["entry"] for row in changed], ["r001/large.bin"])
        self.assertTrue(changed[0]["changed"])
        self.assertNotIn("r001/large.bin", [row["entry"] for row in verified["manifest"]["files"]])
        self.assertIn("1 changed while they were copied", (backup_folder(receipt) / "README.txt").read_text(encoding="utf-8"))

    def test_partial_archive_never_has_final_name(self):
        plan = self.plan()
        seen = []
        real = storage_backup._Member.write

        def look(member, data):
            folder = next(path for path in self.output.iterdir() if FOLDER.fullmatch(path.name))
            seen.append(sorted(os.listdir(folder)))
            return real(member, data)
        with mock.patch.object(storage_backup._Member, "write", look), \
                mock.patch.object(storage_backup, "verify_archive", side_effect=StorageRefusal("fictional failed read-back", code="archive-verification-failed")):
            with self.assertRaises(StorageRefusal):
                self.create(plan)
        self.assertTrue(seen)
        self.assertTrue(all(len(names) == 1 and scoped_base.PARTIAL_NAME.fullmatch(names[0]) for names in seen))
        folder = next(path for path in self.output.iterdir() if FOLDER.fullmatch(path.name))
        self.assertEqual(os.listdir(folder), [])  # no final name, and the temporary file is gone
        attempt = json.loads((self.output / f"attempt-backup-{plan_sha256(plan)}.json").read_bytes())
        self.assertEqual(seen[0], [attempt["partials"]["archive"]])


class InUseTests(BackupFixture, unittest.TestCase):
    def test_file_in_use_refuses_the_backup_with_a_typed_reason_and_no_retry(self):
        plan = self.plan()
        real, calls = scoped_base.RootBase.stream_to, []

        def busy(root, relative, **options):
            if relative == "copy.txt":
                calls.append(relative)
                raise ScopedFSError("sharing-violation", "Another program has the entry open; nothing is retried")
            return real(root, relative, **options)
        with mock.patch.object(scoped_base.RootBase, "stream_to", busy), self.assertRaises(StorageRefusal) as caught:
            self.create(plan)
        self.assertEqual(caught.exception.code, "file-in-use")
        self.assertEqual(str(caught.exception), "A selected file (copy.txt) is in use by another program, so the backup stopped and no "
                                                "backup was made. Close that program, then ask me to plan the backup again.")
        self.assertEqual(calls, ["copy.txt"])  # tried once, never retried
        folder = next(path for path in self.output.iterdir() if FOLDER.fullmatch(path.name))
        self.assertEqual(os.listdir(folder), [])

    def test_a_file_in_use_while_it_is_planned_is_named_too(self):
        inventory = self.inventory()
        selected = [row["key"] for row in inventory["entries"] if row["kind"] == "file"]
        real = ROOT_CLASS.inspect

        def busy(root, relative, **options):
            if options.get("hash_file") and relative == "notes/draft.md":
                raise ScopedFSError("sharing-violation", "Another program has the entry open; nothing is retried")
            return real(root, relative, **options)
        with mock.patch.object(ROOT_CLASS, "inspect", busy), self.assertRaises(StorageRefusal) as caught:
            self.service.plan_backup(inventory=inventory, selected=selected, destination=self.output, content_read_authorized=True)
        self.assertEqual(caught.exception.code, "file-in-use")
        self.assertIn("A selected file (notes/draft.md) is in use", str(caught.exception))


class Stopped(BaseException):
    """Ends a call where a crash would, without being one of the failures the service handles."""


def killed_at_the_first_write(member, data):
    """storage_backup._Member.write of a process killed here: nothing removes the temporary file any more."""
    member.archive.fp.committed = True
    raise Stopped()


# Whether a temporary file a killed backup created can be proven its own afterwards: an NTFS file id carries a sequence
# number, while a POSIX inode number can be given to a later file. The platform decides here, never the code under test.
LASTING_IDS = os.name == "nt"


def inode_record(plan, partial):
    """The identity record a POSIX backup would write if it trusted inode numbers: it names ``partial`` as it is now."""
    info = os.stat(partial)
    return {**storage_policy.storage_value("attempt"), "operation": "backup-temporary-file", "plan_sha256": plan_sha256(plan),
            "name": partial.name, "identity": {"kind": "file", "inode": info.st_ino, "mode": info.st_mode, "nlink": info.st_nlink}}


def fixed_drive():
    """Destinations admitted from now on appear to be on a fixed private drive, whatever disk the test runs on."""
    if os.name == "nt":
        facts = {"filesystem": "NTFS", "removable": False, "drive_type": win32_files.DRIVE_FIXED}
        volumes = lambda handle, drive: facts  # noqa: E731
    else:
        facts = {"filesystem": "native", "removable": False}
        volumes = lambda fd: facts  # noqa: E731
    real = scoped_fs.admit_destination
    return mock.patch.object(scoped_fs, "admit_destination", lambda root, **options: real(root, volumes=volumes, **options))


class SettlementTests(BackupFixture, unittest.TestCase):
    """settle_backup after a process was killed: it removes a temporary file only when that file is provably the one this
    backup created, on the drive reserved for it, and it reads no record the privacy check refuses."""

    def interrupted(self, plan=None, *, service=None):
        """A backup killed at its first write: (plan, attempt record, path of the archive's temporary file)."""
        plan = plan or self.plan()
        with mock.patch.object(storage_backup._Member, "write", killed_at_the_first_write), self.assertRaises(Stopped):
            (service or self.service).create_backup(plan=plan, expected_plan_sha256=plan_sha256(plan))
        attempt = json.loads((self.output / f"attempt-backup-{plan_sha256(plan)}.json").read_bytes())
        partial = Path(plan["destination"]) / attempt["folder"] / attempt["partials"]["archive"]
        self.assertTrue(partial.is_file())
        return plan, attempt, partial

    def settle(self, plan, **options):
        return self.service.settle_backup(plan=plan, expected_plan_sha256=plan_sha256(plan), **options)

    def record_of(self, plan, key="archive"):
        return self.output / f"partial-{key}-{plan_sha256(plan)}.json"

    def test_the_file_this_backup_created_is_removed_only_where_its_id_lasts(self):
        plan, attempt, partial = self.interrupted()
        settled = self.settle(plan)
        if LASTING_IDS:
            self.assertTrue(self.record_of(plan).is_file())
            self.assertEqual(settled, {"state": "removed", "folder": attempt["folder"], "removed": [partial.name], "kept": [], "leftover": []})
            self.assertFalse(partial.exists())
        else:  # nothing records an inode number, and the file stays, named for the person to delete
            self.assertFalse(self.record_of(plan).exists())
            self.assertEqual(settled, {"state": "removed", "folder": attempt["folder"], "removed": [], "kept": [partial.name],
                                       "leftover": [str(partial)]})
            self.assertTrue(partial.is_file())

    def test_a_replaced_file_stays(self):
        plan, attempt, partial = self.interrupted()
        replacement = partial.with_name("fictional-replacement")
        replacement.write_bytes(b"fictional file that took this name")
        os.replace(replacement, partial)
        settled = self.settle(plan)
        self.assertEqual((settled["state"], settled["removed"], settled["kept"]), ("removed", [], [partial.name]))
        self.assertEqual(settled["leftover"], [] if LASTING_IDS else [str(partial)])
        self.assertEqual(partial.read_bytes(), b"fictional file that took this name")

    def test_a_file_deleted_and_made_again_under_its_name_stays(self):
        """After the kill the temporary file is deleted and another is made under its name. NTFS gives the new file another id.
        A POSIX system may give it the old inode number, mode and link count, so there nothing may rest on them: the file stays
        even when the identity of the old file, as an inode record would hold it, is the new file's."""
        plan, attempt, partial = self.interrupted()
        partial.unlink()
        write_private_new(partial, b"fictional file made again under this name")
        if not LASTING_IDS:  # the inode number used again, at its most exact
            write_private_new(self.record_of(plan), canonical(inode_record(plan, partial)))
        settled = self.settle(plan)
        self.assertEqual((settled["state"], settled["removed"], settled["kept"]), ("removed", [], [partial.name]))
        self.assertEqual(settled["leftover"], [] if LASTING_IDS else [str(partial)])
        self.assertEqual(partial.read_bytes(), b"fictional file made again under this name")

    def test_a_file_with_no_recorded_identity_stays(self):
        """The name is recorded and the file is there, but the process died before it recorded what it created."""
        plan, attempt, partial = self.interrupted()
        self.record_of(plan).unlink(missing_ok=not LASTING_IDS)  # POSIX records none
        self.assertEqual(self.settle(plan)["kept"], [partial.name])
        self.assertTrue(partial.is_file())
        self.record_of(plan).write_bytes(b"")  # and a record that holds no identity proves nothing
        if LASTING_IDS:
            with self.assertRaises(StorageRefusal):
                self.settle(plan)
        else:  # where no record can prove a file, none is read
            self.assertEqual(self.settle(plan)["leftover"], [str(partial)])
        self.assertTrue(partial.is_file())

    def test_a_record_of_another_file_proves_nothing(self):
        plan, attempt, partial = self.interrupted()
        # On POSIX not even a record of the file's own inode, unchanged, proves anything.
        data = json.loads(self.record_of(plan).read_bytes()) if LASTING_IDS else inode_record(plan, partial)
        for change in ({"name": scoped_base.new_partial_name()}, {"plan_sha256": "0" * 64}, {"identity": {}}, {"identity": None},
                       *(() if LASTING_IDS else ({},))):
            with self.subTest(change=change):
                self.record_of(plan).unlink(missing_ok=True)
                write_private_new(self.record_of(plan), canonical({**data, **change}))
                self.assertEqual(self.settle(plan)["kept"], [partial.name])
                self.assertTrue(partial.is_file())

    def test_a_drive_whose_file_ids_do_not_last_keeps_the_file(self):
        with mock.patch.object(ROOT_CLASS, "identity_keys", scoped_base.UNSTABLE_ID_KEYS):
            plan, attempt, partial = self.interrupted()
            self.assertFalse(self.record_of(plan).exists())
            settled = self.settle(plan)
        self.assertEqual((settled["kept"], settled["leftover"]), ([partial.name], [str(partial)]))
        self.assertTrue(partial.is_file())

    def external(self):
        """A plan to a chosen folder, and a service holding that folder admitted. Returns (plan, service)."""
        chosen = private_child(self.base, "chosen-drive")
        plan = self.plan(destination=chosen)
        root = scoped_fs.admit_destination(str(chosen), non_private_destination=False)
        service = StorageService(output_root=self.output, quiet_workspace=True, backup_destination=root)
        self.addCleanup(service.close)
        return plan, service

    def test_on_the_wrong_drive_nothing_is_touched_not_even_by_admission(self):
        with fixed_drive():
            plan, service = self.external()
            plan, attempt, partial = self.interrupted(plan, service=service)
            for observed, reserved in (("fictional-other-drive", "fictional-reserved-drive"), (None, "fictional-reserved-drive"),
                                       ("fictional-reserved-drive", None)):
                with self.subTest(observed=observed, reserved=reserved), mock.patch.object(scoped_fs, "volume_identity", return_value=observed), \
                        mock.patch.object(scoped_fs, "admit_destination", side_effect=AssertionError("admission writes on the drive")):
                    settled = self.settle(plan, finish=True, volume_identity=reserved)
                self.assertEqual(settled["state"], "kept")
                self.assertEqual(settled["removed"], [])
                self.assertIn(partial.name, settled["kept"])
                self.assertTrue(partial.is_file())
            with mock.patch.object(scoped_fs, "volume_identity", return_value="fictional-reserved-drive"):
                settled = self.settle(plan, volume_identity="fictional-reserved-drive")
        if LASTING_IDS:
            self.assertEqual((settled["state"], settled["removed"], settled["kept"]), ("removed", [partial.name], []))
            self.assertFalse(partial.exists())
        else:  # on its own drive it is looked at, and stays for the person, as every POSIX temporary file does
            self.assertEqual((settled["state"], settled["removed"], settled["leftover"]), ("removed", [], [str(partial)]))
            self.assertTrue(partial.is_file())

    def test_a_swap_after_the_folder_was_opened_is_caught_before_any_delete(self):
        with fixed_drive():
            plan, service = self.external()
            plan, attempt, partial = self.interrupted(plan, service=service)
            with mock.patch.object(scoped_fs, "volume_identity", side_effect=["fictional-reserved-drive", "fictional-other-drive"]):
                settled = self.settle(plan, volume_identity="fictional-reserved-drive")
        self.assertEqual(settled["state"], "kept")
        self.assertTrue(partial.is_file())

    def stopped_before_the_receipt(self, service=None, plan=None):
        """A backup killed after every file got its final name, before its receipt."""
        plan, real = plan or self.plan(), StorageService._write_record

        def stop_at_the_receipt(own, root, relative, value):
            if relative.startswith("outcome-backup-"):
                raise Stopped()
            return real(own, root, relative, value)
        with mock.patch.object(StorageService, "_write_record", stop_at_the_receipt), self.assertRaises(Stopped):
            (service or self.service).create_backup(plan=plan, expected_plan_sha256=plan_sha256(plan))
        return plan

    def test_a_finished_archive_on_the_wrong_drive_gets_no_receipt_and_no_note(self):
        with fixed_drive():
            plan, service = self.external()
            self.stopped_before_the_receipt(service, plan)
            attempt = json.loads((self.output / f"attempt-backup-{plan_sha256(plan)}.json").read_bytes())
            folder = Path(plan["destination"]) / attempt["folder"]
            (folder / "README.txt").unlink()
            with mock.patch.object(scoped_fs, "volume_identity", return_value="fictional-other-drive"):
                self.assertEqual(self.settle(plan, finish=True, volume_identity="fictional-reserved-drive")["state"], "kept")
            self.assertEqual(sorted(os.listdir(folder)), ["backup.zip", "manifest.json"])
            self.assertFalse((self.output / f"outcome-backup-{plan_sha256(plan)}.json").exists())
            with mock.patch.object(scoped_fs, "volume_identity", return_value="fictional-reserved-drive"):
                self.assertEqual(self.settle(plan, finish=True, volume_identity="fictional-reserved-drive")["state"], "finished")
        self.assertEqual(sorted(os.listdir(folder)), ["README.txt", "backup.zip", "manifest.json"])

    def test_a_receipt_on_the_wrong_drive_is_refused_not_read_back(self):
        with fixed_drive():
            plan, service = self.external()
            service.create_backup(plan=plan, expected_plan_sha256=plan_sha256(plan))
            with mock.patch.object(scoped_fs, "volume_identity", return_value="fictional-other-drive"), self.assertRaises(StorageRefusal) as caught:
                self.settle(plan, volume_identity="fictional-reserved-drive")
            self.assertEqual(caught.exception.code, "drive-not-connected")
            self.assertIn("is not the one this backup was written to", str(caught.exception))
            with mock.patch.object(scoped_fs, "volume_identity", return_value="fictional-reserved-drive"):
                self.assertEqual(self.settle(plan, volume_identity="fictional-reserved-drive")["state"], "finished")

    def test_a_note_file_this_backup_did_not_create_stops_the_finish(self):
        plan = self.stopped_before_the_receipt()
        attempt = json.loads((self.output / f"attempt-backup-{plan_sha256(plan)}.json").read_bytes())
        folder = Path(plan["destination"]) / attempt["folder"]
        name = attempt["partials"]["readme"]
        (folder / "README.txt").unlink()
        (folder / name).write_bytes(b"fictional file that took this name")
        settled = self.settle(plan, finish=True)
        self.assertEqual((folder / name).read_bytes(), b"fictional file that took this name")
        if not LASTING_IDS:  # nothing tells it from the note's own temporary file: it stays, and the note is written afresh
            self.assert_finished_with_a_new_note(plan, settled, folder, name)
            return
        self.assertEqual(settled["state"], "kept")
        self.assertIn(name, settled["kept"])
        self.assertFalse((folder / "README.txt").exists())
        self.assertFalse((self.output / f"outcome-backup-{plan_sha256(plan)}.json").exists())

    def assert_finished_with_a_new_note(self, plan, settled, folder, name):
        """The backup finished: README.txt written under a fresh temporary name, the file at the recorded one left and named."""
        self.assertEqual((settled["state"], settled["leftover"]), ("finished", [str(folder / name)]))
        self.assertTrue((self.output / f"outcome-backup-{plan_sha256(plan)}.json").is_file())
        self.assertEqual(sorted(os.listdir(folder)), sorted(["README.txt", "backup.zip", "manifest.json", name]))
        self.assertIn("files backed up", (folder / "README.txt").read_text(encoding="utf-8"))

    def killed_in_the_note(self, plan):
        """A backup killed while it wrote README.txt, after backup.zip and manifest.json got their final names: its folder and
        the note's recorded temporary name."""
        real = storage_backup.StorageBackup._write_lines

        def killed_in_the_note(destination, relative, partial, chunks, *, created=None):
            if not relative.endswith("/README.txt"):
                return real(destination, relative, partial, chunks, created=created)
            with destination.open_new(relative, partial=partial) as out:
                created(out)
                out.write(b"cut off")
                out.committed = True  # as a killed process: nothing removes it
                raise Stopped()
        with mock.patch.object(storage_backup.StorageBackup, "_write_lines", staticmethod(killed_in_the_note)), self.assertRaises(Stopped):
            self.create(plan)
        attempt = json.loads((self.output / f"attempt-backup-{plan_sha256(plan)}.json").read_bytes())
        folder = Path(plan["destination"]) / attempt["folder"]
        self.assertEqual(sorted(os.listdir(folder)), sorted(["backup.zip", "manifest.json", attempt["partials"]["readme"]]))
        return folder, attempt["partials"]["readme"]

    def test_finishing_writes_a_note_that_was_cut_off_when_the_temporary_file_is_its_own(self):
        plan = self.plan()
        folder, name = self.killed_in_the_note(plan)
        settled = self.settle(plan, finish=True)
        if not LASTING_IDS:  # the cut-off note cannot be proven its own: it stays, named, and the backup still finishes
            self.assert_finished_with_a_new_note(plan, settled, folder, name)
            return
        self.assertEqual((settled["state"], settled["leftover"]), ("finished", []))
        self.assertEqual(sorted(os.listdir(folder)), ["README.txt", "backup.zip", "manifest.json"])
        self.assertIn("files backed up", (folder / "README.txt").read_text(encoding="utf-8"))

    def test_a_note_cut_off_on_a_drive_whose_file_ids_do_not_last_is_written_afresh(self):
        with mock.patch.object(ROOT_CLASS, "identity_keys", scoped_base.UNSTABLE_ID_KEYS):
            plan = self.plan()
            folder, name = self.killed_in_the_note(plan)
            settled = self.settle(plan, finish=True)
        self.assert_finished_with_a_new_note(plan, settled, folder, name)
        self.assertEqual((folder / name).read_bytes(), b"cut off")

    def refused(self, name):
        """The privacy check refuses the record ``name`` and admits everything else."""
        real = storage_policy.ensure_private_file

        def admit(path):
            if Path(path).name == name:
                raise PrivateWorkspaceError("private-owner-or-mode-refused")
            return real(path)
        return mock.patch.object(storage_policy, "ensure_private_file", admit)

    def test_a_refused_attempt_record_is_not_read_and_its_partial_stays(self):
        plan, attempt, partial = self.interrupted()
        with self.refused(f"attempt-backup-{plan_sha256(plan)}.json"), self.assertRaises(StorageRefusal) as caught, \
                mock.patch.object(scoped_base, "hash_stream", side_effect=AssertionError("a refused record was read")):
            self.settle(plan)
        self.assertEqual(caught.exception.code, "private-owner-or-mode-refused")
        self.assertTrue(partial.is_file())

    def test_a_malformed_folder_name_is_refused_before_anything_is_written(self):
        plan = self.plan()
        names, before = self.service.backup_names(plan=plan), sorted(os.listdir(self.output))
        for folder in ("fictional-backup", "../" + names["folder"], names["folder"][:-len("backup")] + "Fictional-backup"):
            with self.subTest(folder=folder), self.assertRaisesRegex(StorageRefusal, "backup_names"):
                self.service.create_backup(plan=plan, expected_plan_sha256=plan_sha256(plan), names={**names, "folder": folder})
        self.assertEqual(sorted(os.listdir(self.output)), before)

    def test_an_attempt_record_with_a_malformed_folder_name_is_refused_and_its_partial_stays(self):
        plan, attempt, partial = self.interrupted()
        record = self.output / f"attempt-backup-{plan_sha256(plan)}.json"
        for folder in ("fictional-backup", "../" + attempt["folder"], attempt["folder"] + "/r001", 42):
            with self.subTest(folder=folder):
                record.unlink()
                write_private_new(record, canonical({**attempt, "folder": folder}))
                with self.assertRaisesRegex(StorageRefusal, "not this plan's"):
                    self.settle(plan)
        self.assertTrue(partial.is_file())

    def test_a_refused_receipt_is_not_read(self):
        plan = self.plan()
        receipt = self.create(plan)
        with self.refused(f"outcome-backup-{plan_sha256(plan)}.json"), self.assertRaises(StorageRefusal) as caught:
            self.settle(plan)
        self.assertEqual(caught.exception.code, "private-owner-or-mode-refused")
        self.assertEqual(self.settle(plan)["receipt"], receipt)

    def test_a_refused_identity_record_keeps_the_file(self):
        plan, attempt, partial = self.interrupted()
        if not LASTING_IDS:  # POSIX writes none; one put there is never read, so it is not refused either
            write_private_new(self.record_of(plan), canonical(inode_record(plan, partial)))
            with self.refused(self.record_of(plan).name):
                self.assertEqual(self.settle(plan)["leftover"], [str(partial)])
            self.assertTrue(partial.is_file())
            return
        with self.refused(self.record_of(plan).name), self.assertRaises(StorageRefusal) as caught:
            self.settle(plan)
        self.assertEqual(caught.exception.code, "private-owner-or-mode-refused")
        self.assertTrue(partial.is_file())

    @unittest.skipUnless(os.name == "posix", "only on posix: a record's mode can be widened there; Windows goes through the fake above")
    def test_a_record_another_account_can_read_is_refused_for_real(self):
        plan, attempt, partial = self.interrupted()
