class BackupVerificationTests(BackupFixture, unittest.TestCase):
    def test_verification_streams_every_entry_against_source_hash(self):
        receipt = self.create(self.plan())
        opened, real = [], zipfile.ZipFile.open

        def spy(archive, name, *args, **kwargs):
            opened.append(name.filename if isinstance(name, zipfile.ZipInfo) else name)
            return real(archive, name, *args, **kwargs)
        with mock.patch.object(zipfile.ZipFile, "open", spy):
            verified = self.service.verify_backup(receipt=receipt, archive_data=False)
        self.assertEqual(opened, [row["entry"] for row in verified["manifest"]["entries"]])
        for row in verified["manifest"]["entries"]:
            self.assertEqual(row["sha256"], hashlib.sha256((self.source / row["relative_path"]).read_bytes()).hexdigest())
        self.assertIn("read back from the disk", receipt["verification"])
        self.assertIn("does not test the drive itself", receipt["verification"])

    def test_corrupted_archive_fails_verification(self):
        receipt = self.create(self.plan())
        archive = backup_folder(receipt) / "backup.zip"
        data = bytearray(archive.read_bytes())
        with zipfile.ZipFile(io.BytesIO(bytes(data))) as reader:
            info = reader.getinfo("r001/large.bin")
        name_length, extra_length = struct.unpack("<HH", data[info.header_offset + 26:info.header_offset + 30])
        data[info.header_offset + 30 + name_length + extra_length + 3] ^= 0x55  # inside the member's compressed bytes
        rows = self.service.verify_backup(receipt=receipt, archive_data=False)["manifest"]["entries"]
        with self.assertRaises(StorageRefusal) as caught:
            storage_verify.verify_archive(io.BytesIO(bytes(data)), rows)
        self.assertEqual(caught.exception.code, "archive-verification-failed")
        archive.write_bytes(bytes(data))
        with self.assertRaises((StorageRefusal, ScopedFSError)):
            self.service.verify_backup(receipt=receipt, archive_data=False)


def archive_bytes(rows, contents, *, mutate=None):
    """An archive written the way the backup writes it, for the rows' entries, with each content."""
    stream = io.BytesIO()
    with zipfile.ZipFile(stream, "w", compression=zipfile.ZIP_DEFLATED) as archive:
        for row, content in zip(rows, contents):
            with archive.open(storage_backup.entry_info(row["entry"], 0), "w", force_zip64=True) as member:
                member.write(content)
    data = bytearray(stream.getvalue())
    if mutate:
        mutate(data)
    return bytes(data)


def row_for(relative, content, root_id="r001"):
    return {"entry": root_id + "/" + relative, "root_id": root_id, "relative_path": relative, "size": len(content),
            "sha256": hashlib.sha256(content).hexdigest(), "changed": False}


class ArchiveNameTests(unittest.TestCase):
    """The names and structure verify_archive refuses (every one before any byte is restored)."""

    def test_names_must_be_the_manifest_validated_path(self):
        good = row_for("notes/a.txt", b"fictional")
        self.assertEqual(storage_verify.verify_archive(io.BytesIO(archive_bytes([good], [b"fictional"])), [good]), 1)
        for relative in ("../escape.txt", "notes/../../x", "C:/Windows/x", "/absolute.txt", "back\\slash.txt", "a.txt:stream",
                         "CON", "notes/nul.txt", ".ssh/id_ed25519"):
            with self.subTest(relative=relative):
                bad = {**good, "relative_path": relative, "entry": "r001/" + relative}
                with self.assertRaises(StorageRefusal):
                    storage_verify.verify_archive(io.BytesIO(archive_bytes([good], [b"fictional"])), [bad])
        upper = row_for("NOTES/A.TXT", b"fictional")
        with self.assertRaisesRegex(StorageRefusal, "Case-ambiguous"):
            storage_verify.verify_archive(io.BytesIO(archive_bytes([good, upper], [b"fictional"] * 2)), [good, upper])
        renamed = {**good, "entry": "r001/notes/b.txt"}
        with self.assertRaisesRegex(StorageRefusal, "validated path"):
            storage_verify.verify_archive(io.BytesIO(archive_bytes([good], [b"fictional"])), [renamed])
        with self.assertRaises(StorageRefusal):
            storage_verify.verify_archive(io.BytesIO(archive_bytes([good], [b"fictional"])), [{**good, "root_id": "../r"}])

    def test_structure_extra_members_overlap_and_ratio_are_refused(self):
        rows = [row_for("a.txt", b"fictional a"), row_for("b.txt", b"fictional b")]
        data = archive_bytes(rows, [b"fictional a", b"fictional b"])
        with self.assertRaisesRegex(StorageRefusal, "exact reviewed list"):
            storage_verify.verify_archive(io.BytesIO(data), rows[:1])
        with self.assertRaisesRegex(StorageRefusal, "hash mismatch"):
            storage_verify.verify_archive(io.BytesIO(data), [rows[0], {**rows[1], "sha256": "0" * 64}])

        def rename_local(raw):  # the second local header names another file than its central directory entry
            offset = raw.index(b"r001/b.txt")
            raw[offset + 5] = ord("c")
        with self.assertRaises(StorageRefusal):
            storage_verify.verify_archive(io.BytesIO(archive_bytes(rows, [b"fictional a", b"fictional b"], mutate=rename_local)), rows)
        zeros = row_for("zeros.bin", bytes(1 << 20))

        def tiny_compressed_size(raw):  # the central directory claims 1 MiB from 1 byte: refused before inflating
            offset = raw.index(b"PK")
            raw[offset + 20:offset + 24] = (1).to_bytes(4, "little")
        with self.assertRaisesRegex(StorageRefusal, "oversized"):
            storage_verify.verify_archive(io.BytesIO(archive_bytes([zeros], [bytes(1 << 20)], mutate=tiny_compressed_size)), [zeros])
        prefixed = b"x" * 10 + data
        with self.assertRaises(StorageRefusal):
            storage_verify.verify_archive(io.BytesIO(prefixed), rows)


class StorageCliTests(unittest.TestCase):
    def test_storage_cli_refuses_without_isolated_flags(self):
        script = str(SCRIPTS / "patchcairn_storage.py")
        environment = {key: value for key, value in os.environ.items() if not key.startswith("PYTHON")}
        refused = subprocess.run([sys.executable, "-S", "-B", script, "capabilities", "--json"], capture_output=True,
                                 encoding="utf-8", errors="replace", env=environment, timeout=120)
        self.assertEqual(refused.returncode, 2)
        self.assertIn("interpreter-not-isolated", refused.stderr)
        self.assertEqual(refused.stdout, "")
        no_site = subprocess.run([sys.executable, "-I", "-B", script, "capabilities", "--json"], capture_output=True,
                                 encoding="utf-8", errors="replace", timeout=120)
        self.assertEqual((no_site.returncode, "interpreter-not-isolated" in no_site.stderr), (2, True))
        allowed = subprocess.run([sys.executable, "-I", "-S", "-B", script, "capabilities", "--json"], capture_output=True,
                                 encoding="utf-8", errors="replace", timeout=120)
        self.assertEqual(allowed.returncode, 0, allowed.stderr)
        self.assertFalse(json.loads(allowed.stdout)["cli_mutation_enabled"])


class GoldenLayoutTests(BackupFixture, unittest.TestCase):
    """The exact key sets of the records whose layout changed: the manifest header and entry lines, the receipt and
    the attempt record. A change here changes what restore, removal and the retention registry read."""

    def test_manifest_receipt_and_attempt_layouts(self):
        plan = self.plan(["r001/readme.txt"])
        receipt = self.create(plan)
        lines = (backup_folder(receipt) / "manifest.json").read_bytes().split(b"\n")
        header, entry = json.loads(lines[0]), json.loads(lines[1])
        self.assertEqual(sorted(header), ["archive", "changed_count", "compression_is_not_encryption", "created_utc", "entry_count",
                                          "format", "kind", "plan_sha256", "required_recovery", "schema", "schema_version",
                                          "skipped_count", "source_logical_bytes", "source_roots"])
        self.assertEqual(sorted(entry), ["attributes", "changed", "crc32", "ctime_ns", "dacl_protected", "device", "entry", "inode",
                                         "key", "kind", "mode", "mtime_ns", "nlink", "read_only", "relative_path", "root_id", "sha256", "size"])
        self.assertEqual(lines[1], canonical(entry))  # each line is the canonical encoding of its row
        self.assertEqual(sorted(receipt), sorted([
            "schema", "schema_version", "kind", "plan_sha256", "outcome", "destination", "folder", "location", "external", "private",
            "archive", "archive_record", "archive_sha256", "manifest", "manifest_record", "manifest_sha256", "readme", "readme_sha256",
            "durable", "entry_count", "changed_count", "not_included_count", "required_recovery", "verified", "verification",
            "encryption", "volume_identity", "sources_synced", "disk_relation", "attempt", "actual_archive_bytes",
            "archive_and_manifest_bytes", "backup_bytes", "control_record_bytes", "source_logical_bytes", "finished_utc"]))
        self.assertTrue(receipt["volume_identity"] is None or isinstance(receipt["volume_identity"], str))
        attempt = json.loads((self.output / receipt["attempt"]).read_bytes())
        self.assertEqual(sorted(attempt), ["automatic_retry", "entry_count", "folder", "kind", "operation", "partials", "plan_file",
                                           "plan_sha256", "schema", "schema_version", "started_utc", "status"])
        self.assertEqual(sorted(plan["cost"]), ["archive_bytes_at_most", "control_record_bytes", "duration_seconds",
                                                "manifest_bytes_at_most", "money", "net_free_space_change_bytes",
                                                "peak_process_memory", "source_logical_bytes", "stream_chunk_bytes"])

    def test_plan_reports_measured_control_record_bytes_and_streaming_memory(self):
        plan = self.plan()
        cost = plan["cost"]
        self.assertIs(type(cost["control_record_bytes"]), int)
        self.assertGreater(cost["control_record_bytes"], len(canonical(plan)))
        self.assertEqual(cost["stream_chunk_bytes"], scoped_base.CHUNK_BYTES)
        self.assertIn("1 MiB pieces", cost["peak_process_memory"])
        self.assertNotIn("bounded_payload_buffer_bytes", cost)
        receipt = self.create(plan)
        self.assertEqual(receipt["control_record_bytes"], sum(path.stat().st_size for path in self.output.iterdir() if path.is_file()
                                                              and not path.name.startswith("outcome-backup-")))


class GoldenBytesTests(unittest.TestCase):
    """The exact bytes of the new layouts (manifest.json, the attempt record with the run-time names, the receipt) for
    fixed fictional inputs; a change here is a format change that restore, removal and retention must follow."""

    CLOCK, DIGEST = "2026-01-01T00:00:00.000000Z", "0" * 64
    ROW = {"entry": "r001/a.txt", "root_id": "r001", "key": "r001/a.txt", "relative_path": "a.txt", "kind": "file", "device": 1,
           "inode": 2, "mode": 0o100600, "size": 9, "mtime_ns": 0, "ctime_ns": 0, "nlink": 1,
           "sha256": hashlib.sha256(b"fictional").hexdigest(), "attributes": 0}
    PINNED = {"manifest": "a20c1e243cbef2fe9d1bc460a647afed07affe174f1553afcbae3fd47031e435",
              "attempt": "e411cc41982c39a4851e05b47228b6271b3a8976e37a8af13aade7205a51261f",
              # The receipt holds paths, which Windows writes with backslashes.
              "receipt": "88acbc193d3219c39ab7e28a820e67a83d76e7fd63ff4dd19409fde91640822a" if os.name == "nt"
                         else "33bfdd1f5c8d52421483ad7a4f0461f0f1f6ce39a1bff851d12b2d9428de4b4c"}

    def test_new_layouts_have_pinned_bytes(self):
        plan = {"required_recovery": True, "external": False, "destination": "/fictional/backups", "sources_synced": [],
                "inventory": {"roots": [{"root_id": "r001", "path": "/fictional/source", "record": {"device": 1, "inode": 1, "mode": 0o40700}}]},
                "skipped": [{"key": "r001/b.txt", "kind": "file", "reason": "not selected; not backed up"}], "files": [self.ROW]}
        rows = [{**self.ROW, "crc32": 123456789, "read_only": False, "dacl_protected": None, "changed": False}]
        names = {"folder": "20260101T000000Z-backup", "partials": {"archive": ".partial-" + "a" * 32, "manifest": ".partial-" + "b" * 32,
                                                                  "readme": ".partial-" + "c" * 32}}
        records = tuple({"relative_path": "20260101T000000Z-backup/" + name, "size": size, "sha256": letter * 64, "durable": True}
                        for name, size, letter in (("backup.zip", 100, "1"), ("manifest.json", 50, "2"), ("README.txt", 10, "3")))
        destination = mock.Mock(private=True)
        with mock.patch("pc_records.utc_now", return_value=self.CLOCK), mock.patch("scoped_fs.volume_identity", return_value=None):
            manifest = b"".join(storage_backup.StorageBackup._manifest_lines(plan, self.DIGEST, rows))
            attempt = canonical(storage_policy.attempt_record("backup", self.DIGEST, f"plan-backup-{self.DIGEST}.json", plan, **names))
            receipt = canonical(storage_backup.StorageBackup._receipt(plan, self.DIGEST, names["folder"], destination, {}, rows, records, 1234))
        actual = {name: hashlib.sha256(data).hexdigest() for name, data in (("manifest", manifest), ("attempt", attempt), ("receipt", receipt))}
        self.assertEqual(actual, self.PINNED)
        self.assertEqual(manifest.count(b"\n"), 3)  # header, one entry, one left-out entry


class NotIncludedTests(BackupFixture, unittest.TestCase):
    def test_online_only_placeholder_is_listed_as_not_included(self):
        record = {"kind": "file", "device": 7, "inode": 11, "mode": 0o100600, "size": 5, "mtime_ns": 1, "ctime_ns": 1, "nlink": 1,
                  "sha256": None, "attributes": 0}

        class FakeRoot:
            def __init__(self, path, *, quiet_workspace, max_entries):
                pass

            def __enter__(self):
                return self

            def __exit__(self, *unused):
                return False

            def inspect(self, relative):
                return {**record, "relative_path": relative, "kind": "directory", "inode": 1}

            def list_directory(self, relative, *, excluded):
                scoped_base.exclude(excluded, "", "cloud.docx", "online-only")
                return [{**record, "relative_path": "ok.txt", "inode": 12}]
        with mock.patch("storage_policy.ScopedRoot", FakeRoot):
            inventory = self.service.assess_storage(roots=[self.source])
        self.assertEqual(inventory["not_included"], [{"root_id": "r001", "parent": "", "name": "cloud.docx", "reason": "online-only"}])
        self.assertIn("never downloaded", storage_backup.NOT_INCLUDED["online-only"])


